  default_code_task_intent_json, implementation_provider_id,
  implementation_kind, implementation_type, status, visibility, tags_json,
  allowed_role_codes, created_at, updated_at, deleted_at, version
) VALUES (
  366800000000000331, 'bdea8e2a-d3af-4305-808b-cee6e85da7b2', 100001, 0, 1,
  'agent.expert.zk-steward', 'expert-zk-steward',
  'ZK Steward', 'Knowledge-base steward in the spirit of Niklas Luhmann''s Zettelkasten. Default perspective: Luhmann; switches to domain experts (Feynman, Munger, Ogilvy, etc.) by task. Enforces atomic notes, connectivity, and validation loops. Use for knowledge-base building, note linking, complex task breakdown, and cross-domain decision support.',
  '{"schema_version":"1.0.0","manifest_type":"agent","agent_id":"agent.expert.zk-steward","name":"expert-zk-steward","display_name":"ZK Steward","description":"Knowledge-base steward in the spirit of Niklas Luhmann''s Zettelkasten. Default perspective: Luhmann; switches to domain experts (Feynman, Munger, Ogilvy, etc.) by task. Enforces atomic notes, connectivity, and validation loops. Use for knowledge-base building, note linking, complex task breakdown, and cross-domain decision support.","version":"1.0.0","domain":"experts","agent_kind":"conversation","category_code":"expert-specialized","runtime":{"family":"sdkwork","engine":"sdkwork","capabilities":["model.chat"]},"required_capabilities":["model.chat"],"event_families":["agent.lifecycle"],"expert":{"slug":"zk-steward","division_code":"specialized","emoji":"🗃️","roster_version":"1.0.0","persona_locales":["zh-CN","en-US"]},"owner_name":"SDKWork","status":"active"}'::jsonb, '1.0.0', NULL, NULL,
