  examples_en_json, coordinator_mode, coordinator_template_id,
  coordinator_template_version, status, sort_order, version, created_by,
  updated_by, created_at, updated_at, deleted_at, deleted_by
) VALUES (
  370000000000000001, '6acce104-a211-47bb-8493-2733b6c8f0c9', 100001, 0,
  'team-product', '产品方案评审团', 'Product Review Team',
  '适合需求评审、方案比较与迭代规划。结合用户价值、使用体验和实现成本，明确首版范围、功能优先级及下一步行动。', 'Review requirements, compare options and plan iterations. Balance user value, usability and implementation cost to define scope, priorities and next steps.',
  '["需求评审","方案比较","迭代规划"]'::jsonb, '["Requirements","Comparison","Planning"]'::jsonb,
  '从价值、体验和可行性评估产品方案。', 'Evaluate the value, usability and feasibility of a product proposal.', '仅进行分析评审；依据不足时明确说明，不擅自修改或发布。',
  '优先级与行动清单', 'Prioritized decisions and an action checklist',
  '["评估这份需求，明确首版必须做和可以暂缓的功能。","比较两个产品方案，给出价值、体验和成本上的取舍。","根据现有功能和用户反馈，制定下一阶段迭代计划。"]'::jsonb, '["Review these requirements and separate essential first-release features from work that can wait.","Compare these product options and explain the trade-offs in value, usability and cost.","Plan the next iteration using existing features and user feedback."]'::jsonb,
  'template', 'product', 1,
  1, 10, 0, 1, 1,
  TIMESTAMPTZ '2026-11-25T00:00:00+08:00', TIMESTAMPTZ '2026-11-25T00:00:00+08:00', NULL, NULL
)
