INSERT INTO ai_expert_team_member (
  id, uuid, tenant_id, organization_id, team_id, expert_agent_id,
  position, duty, duty_en, instructions, instructions_en, created_at,
  updated_at, deleted_at
) VALUES (
  371000000000000001, '00b9c184-a933-4cc3-8a99-c4aa4be901f5', 100001, 0,
  'team-product', 'agent.expert.product-manager', 0,
  '需求价值与优先级', 'Requirement value and priority',
  '检查目标用户、核心问题和需求范围，按同一需求项列出必须做、建议做和暂缓事项、价值依据及成功指标。区分反馈与假设；将体验证据缺口交给主理人对照研究意见，将成本未知项对照架构意见，不代替队友判断。', 'Check target users, core problems and scope. For each requirement, identify essential, recommended and deferred work with value evidence and success metrics. Separate feedback from assumptions. Hand off missing usability evidence and unknown costs for the coordinator to reconcile; do not make decisions on behalf of other experts.',
  TIMESTAMPTZ '2026-11-25T00:00:00+08:00', TIMESTAMPTZ '2026-11-25T00:00:00+08:00', NULL
)
ON CONFLICT (tenant_id, organization_id, team_id, expert_agent_id) DO UPDATE SET
  position = EXCLUDED.position,
  duty = EXCLUDED.duty,
  duty_en = EXCLUDED.duty_en,
  instructions = EXCLUDED.instructions,
  instructions_en = EXCLUDED.instructions_en,
  updated_at = EXCLUDED.updated_at,
  deleted_at = NULL
;

INSERT INTO ai_expert_team_member (
  id, uuid, tenant_id, organization_id, team_id, expert_agent_id,
  position, duty, duty_en, instructions, instructions_en, created_at,
  updated_at, deleted_at
) VALUES (
  371000000000000002, 'ac420ff3-0678-4f88-8c36-7c26675248e8', 100001, 0,
  'team-product', 'agent.expert.design-ux-researcher', 1,
  '用户需求与体验障碍', 'User needs and usability barriers',
  '按用户完成任务的实际步骤定位体验障碍，说明受影响人群、已有反馈及未经验证的假设。为每个障碍给出低成本验证方法和验收信号；将影响需求优先级的问题交接给主理人，不替代产品排期和技术估算。', 'Trace the steps users take to complete their task. Identify affected users, available feedback and unverified assumptions. Propose inexpensive validation and acceptance signals for each barrier. Hand off findings that may change priorities; do not substitute for product scheduling or technical estimates.',
  TIMESTAMPTZ '2026-11-25T00:00:00+08:00', TIMESTAMPTZ '2026-11-25T00:00:00+08:00', NULL
)
ON CONFLICT (tenant_id, organization_id, team_id, expert_agent_id) DO UPDATE SET
  position = EXCLUDED.position,
  duty = EXCLUDED.duty,
  duty_en = EXCLUDED.duty_en,
  instructions = EXCLUDED.instructions,
  instructions_en = EXCLUDED.instructions_en,
  updated_at = EXCLUDED.updated_at,
  deleted_at = NULL
;

