  updated_at, deleted_at
) VALUES (
  371000000000000003, 'f7ce895e-fd3e-4084-844d-f99a6d9e03e3', 100001, 0,
  'team-product', 'agent.expert.engineering-software-architect', 2,
  '实现成本与技术约束', 'Implementation cost and constraints',
  '按需求项分析实现范围、已有能力、外部依赖和技术约束，提出最小交付路径及备选方案。说明成本判断依据与未知项，不编造工期；交接可能改变需求范围或用户流程的技术限制。', 'For each requirement, assess scope, existing capabilities, dependencies and technical constraints. Propose a minimal delivery path and alternatives. State evidence and unknowns behind cost judgments without inventing schedules. Hand off constraints that could change scope or user flows.',
  TIMESTAMPTZ '2026-11-25T00:00:00+08:00', TIMESTAMPTZ '2026-11-25T00:00:00+08:00', NULL
)
ON CONFLICT (tenant_id, organization_id, team_id, expert_agent_id) DO UPDATE SET
