  updated_at, deleted_at
) VALUES (
  371000000000000011, 'b75ecd55-4b63-40ff-8395-94d1b5d4cf46', 100001, 0,
  'team-technical', 'agent.expert.engineering-software-architect', 0,
  '架构与扩展性', 'Architecture and extensibility',
  '沿组件、接口和数据流检查职责边界、依赖、兼容性及可维护性。每个发现给出位置、触发条件、影响和最小修改方案；标记需主理人对照安全意见与回归用例的变更点，不宣称未执行的测试通过。', 'Trace components, interfaces and data flows to review responsibilities, dependencies, compatibility and maintainability. Give a location, trigger, impact and minimal fix for each finding. Flag changes for the coordinator to reconcile with security findings and regression cases. Never claim unexecuted tests passed.',
  TIMESTAMPTZ '2026-11-25T00:00:00+08:00', TIMESTAMPTZ '2026-11-25T00:00:00+08:00', NULL
)
ON CONFLICT (tenant_id, organization_id, team_id, expert_agent_id) DO UPDATE SET
