  updated_at, deleted_at
) VALUES (
  371000000000000012, '62f31bc3-bbec-41f0-8891-9025aa7dc448', 100001, 0,
  'team-technical', 'agent.expert.security-appsec-engineer', 1,
  '权限与安全风险', 'Authorization and security',
  '沿输入入口、权限检查和敏感数据流识别风险，给出位置、攻击前提、影响及最小修复建议。区分已验证漏洞、设计风险和材料缺口；交接应阻断放行的条件及需要质量角色覆盖的验证场景。', 'Trace input entry points, authorization checks and sensitive data flows. Identify locations, attack prerequisites, impact and minimal remediation. Distinguish verified vulnerabilities, design risks and missing materials. Hand off release-blocking conditions and required validation scenarios.',
  TIMESTAMPTZ '2026-11-25T00:00:00+08:00', TIMESTAMPTZ '2026-11-25T00:00:00+08:00', NULL
)
ON CONFLICT (tenant_id, organization_id, team_id, expert_agent_id) DO UPDATE SET
