  updated_at, deleted_at
) VALUES (
  371000000000000013, '57f9b78b-2a0e-46d1-88a2-6e1a7da6a4ab', 100001, 0,
  'team-technical', 'agent.expert.testing-reality-checker', 2,
  '验收边界与质量', 'Acceptance boundaries and quality',
  '依据现有方案独立列出正常、异常、边界、兼容与回滚场景，逐项写明前置条件、操作和预期结果。区分实际执行结果与建议用例；交接需主理人结合架构和安全发现补充的覆盖点，不假设已经拿到队友报告。', 'Independently specify normal, exceptional, boundary, compatibility and rollback scenarios with prerequisites, actions and expected results. Distinguish executed results from proposed tests. Hand off coverage to reconcile with architecture and security findings; do not assume access to other members’ reports.',
  TIMESTAMPTZ '2026-11-25T00:00:00+08:00', TIMESTAMPTZ '2026-11-25T00:00:00+08:00', NULL
)
