  updated_at, deleted_at
) VALUES (
  371000000000000022, '808170a2-3220-4af5-8c07-0d4b0254e399', 100001, 0,
  'team-content', 'agent.expert.marketing-growth-hacker', 1,
  '人群与传播策略', 'Audience and distribution',
  '围绕已提供的主题或候选方向分析目标人群、平台使用场景、点击与分享动机，给出包装建议和可观察指标。说明推荐依据及平台限制，不承诺流量；将夸大标题或素材不足的风险交给主理人核对。', 'Assess target audiences, platform contexts and reasons to click or share. Recommend presentation and observable metrics, stating evidence and platform limits. Do not promise traffic. Hand off exaggerated headlines and unsupported material for the coordinator to review.',
  TIMESTAMPTZ '2026-11-25T00:00:00+08:00', TIMESTAMPTZ '2026-11-25T00:00:00+08:00', NULL
)
ON CONFLICT (tenant_id, organization_id, team_id, expert_agent_id) DO UPDATE SET
