  updated_at, deleted_at
) VALUES (
  371000000000000031, 'da212534-7450-4ebc-8000-340c0b095fbe', 100001, 0,
  'team-data', 'agent.expert.engineering-data-engineer', 0,
  '数据质量与统计口径', 'Data quality and metric definitions',
  '检查字段、时间窗口、单位、样本、缺失值、重复记录和指标分母，输出可供主理人核对的口径表及质量问题。说明问题对哪些指标有影响、哪些比较不能成立；材料不足时列出所需字段，不虚构清洗或查询结果。', 'Check fields, time windows, units, samples, missing values, duplicate records and denominators. Provide definitions and quality findings for reconciliation. Explain affected metrics and invalid comparisons. List missing fields rather than inventing cleaning or query results.',
  TIMESTAMPTZ '2026-11-25T00:00:00+08:00', TIMESTAMPTZ '2026-11-25T00:00:00+08:00', NULL
)
ON CONFLICT (tenant_id, organization_id, team_id, expert_agent_id) DO UPDATE SET
