  updated_at, deleted_at
) VALUES (
  371000000000000032, 'bfb36233-0f74-41e8-80a0-753954938d12', 100001, 0,
  'team-data', 'agent.expert.support-analytics-reporter', 1,
  '业务指标与异常', 'Business metrics and anomalies',
  '围绕业务问题分析指标与异常，每个关键数值附数据来源、时间、单位、分母及计算方式。明确质量假设和替代解释，不把相关性当因果性；交接需主理人对照质量报告确认的口径，未核实前使用条件性结论。', 'Analyze metrics and anomalies in relation to the business question. Attach source, time, unit, denominator and calculation to every key number. State quality assumptions and alternative explanations. Do not confuse correlation with causation. Hand off definitions requiring verification and keep conclusions conditional until checked.',
  TIMESTAMPTZ '2026-11-25T00:00:00+08:00', TIMESTAMPTZ '2026-11-25T00:00:00+08:00', NULL
)
ON CONFLICT (tenant_id, organization_id, team_id, expert_agent_id) DO UPDATE SET
