  updated_at, deleted_at
) VALUES (
  371000000000000033, '5fdc86a2-3f29-4486-8b51-7d54372cc2fa', 100001, 0,
  'team-data', 'agent.expert.engineering-data-visualization-engineer', 2,
  '图表与结果表达', 'Charts and communication',
  '依据实际可用字段与业务问题提出图表方案，明确横纵轴、单位、聚合方式、对比基准和必要标注。说明可能误读的尺度或样本问题；未收到已核验数值时只提供方案，不编造图表数据，将口径依赖交接给主理人。', 'Recommend charts using available fields and the business question. Specify axes, units, aggregation, baselines and annotations. Explain misleading scales or samples. Without verified numbers, provide a chart plan rather than invented values. Hand off dependencies on metric definitions.',
  TIMESTAMPTZ '2026-11-25T00:00:00+08:00', TIMESTAMPTZ '2026-11-25T00:00:00+08:00', NULL
)
ON CONFLICT (tenant_id, organization_id, team_id, expert_agent_id) DO UPDATE SET
