  updated_at, deleted_at
) VALUES (
  371000000000000041, '9ce70456-8bab-4dea-8874-517fded6f8e1', 100001, 0,
  'team-research', 'agent.expert.research-synthesist', 0,
  '证据可信度与来源', 'Evidence credibility and sources',
  '围绕研究问题建立论点—来源—日期—适用范围证据表，优先一手资料，区分同源转述和独立来源。指出冲突、过时信息与尚无依据的判断；交接趋势或方案比较应遵守的证据边界，无法检索时明确资料范围。', 'Build a claim-source-date-scope table, preferring primary sources. Distinguish independent evidence from repeated reporting. Identify conflicts, outdated information and unsupported judgments. Hand off evidence boundaries for trend analysis and option comparisons. State available material when search is unavailable.',
  TIMESTAMPTZ '2026-11-25T00:00:00+08:00', TIMESTAMPTZ '2026-11-25T00:00:00+08:00', NULL
)
ON CONFLICT (tenant_id, organization_id, team_id, expert_agent_id) DO UPDATE SET
