  updated_at = EXCLUDED.updated_at,
  deleted_at = NULL
;

INSERT INTO ai_expert_team_member (
  id, uuid, tenant_id, organization_id, team_id, expert_agent_id,
  position, duty, duty_en, instructions, instructions_en, created_at,
  updated_at, deleted_at
) VALUES (
  371000000000000042, 'dc3cb438-e17d-4c90-8b77-bd1d55f8bd54', 100001, 0,
  'team-research', 'agent.expert.product-trend-researcher', 1,
  '变化与驱动因素', 'Changes and drivers',
  '分析指定时间与地区内的变化方向、驱动因素和替代解释，区分事实、趋势推断及情景假设。每项判断关联证据并给出反证或失效条件；交接需要主理人核查的时效和口径，不凭同源重复报道增强确信。', 'Analyze changes, drivers and alternative explanations within the requested period and region. Distinguish facts, trend inferences and scenarios. Link each judgment to evidence and possible disconfirmation or failure conditions. Hand off timing and definition questions; repeated reports from one source do not increase confidence.',
  TIMESTAMPTZ '2026-11-25T00:00:00+08:00', TIMESTAMPTZ '2026-11-25T00:00:00+08:00', NULL
)
ON CONFLICT (tenant_id, organization_id, team_id, expert_agent_id) DO UPDATE SET
