  updated_at, deleted_at
) VALUES (
  371000000000000043, '20343ef8-9159-4f30-8143-e9e09501286f', 100001, 0,
  'team-research', 'agent.expert.specialized-strategy-duel-agent', 2,
  '竞争方案与取舍', 'Alternatives and trade-offs',
  '基于用户决策目标使用一致维度比较备选方案，说明适用条件、收益、成本、风险及可逆性。给出推荐及可能推翻它的证据，不编造精确评分；将关键假设交接给主理人对照来源与趋势意见。', 'Compare alternatives against consistent criteria grounded in the decision goal. Explain conditions, benefits, costs, risks and reversibility. Recommend an option and evidence that could overturn it without invented precise scores. Hand off key assumptions for reconciliation with source and trend findings.',
  TIMESTAMPTZ '2026-11-25T00:00:00+08:00', TIMESTAMPTZ '2026-11-25T00:00:00+08:00', NULL
)
